<main style="box-sizing:border-box;margin:0;padding:0;width:100%;min-height:1090px;font-family:Arial,sans-serif;font-size:12px;line-height:1.45;color:#18222d;display:flex;flex-direction:column"><header style="box-sizing:border-box;background:#1f5f99;color:#fff;padding:22px 32px;display:flex;justify-content:space-between;align-items:center;gap:20px"><div style="display:flex;align-items:center;gap:14px;min-width:0;flex:1">{{blocks.company_logo}}<div style="min-width:0"><div style="font-size:16px;font-weight:700">{{company.name}}</div><div style="font-size:10.5px;line-height:1.5">{{company.address}}<br>{{company.phone}} · {{company.email}} · GSTIN {{company.gstin}}</div></div></div><div style="text-align:right;flex:none"><h1 style="margin:0;font-size:24px;letter-spacing:.04em">QUOTATION</h1><div style="font-size:11.5px;margin-top:3px">{{report.number}} · {{report.date}}</div></div></header><div style="box-sizing:border-box;flex:1;padding:20px 32px 26px;display:flex;flex-direction:column"><div style="flex:1"><div style="display:flex;gap:16px;margin-bottom:14px"><div style="flex:1;min-width:0;background:#f4f6f8;border-radius:6px;padding:9px 12px"><div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:#5d6b79;margin-bottom:4px">Prepared for</div><strong>{{customer.name}}</strong><br>{{customer.mobile}}</div><div style="flex:1;min-width:0;background:#f4f6f8;border-radius:6px;padding:9px 12px"><div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:#5d6b79;margin-bottom:4px">Vehicle</div><strong>{{vehicle.registration}}</strong> · {{vehicle.description}}<br>{{vehicle.km}} km · Job {{job.number}}</div></div><table style="width:100%;border-collapse:collapse;margin:0 0 12px"><thead><tr><th style="background:#1f5f99;color:#fff;padding:7px 9px;text-align:left;font-size:11px;font-weight:700">Description</th><th style="background:#1f5f99;color:#fff;padding:7px 9px;text-align:right;font-size:11px;font-weight:700">Qty</th><th style="background:#1f5f99;color:#fff;padding:7px 9px;text-align:right;font-size:11px;font-weight:700">Rate</th><th style="background:#1f5f99;color:#fff;padding:7px 9px;text-align:right;font-size:11px;font-weight:700">Amount</th></tr></thead><tbody>{{#lines}}<tr><td style="border-bottom:1px solid #d5dce3;padding:7px 9px;text-align:left;vertical-align:top">{{line.description}}<br><span style="font-size:10px;color:#5d6b79">{{line.kind}}</span></td><td style="border-bottom:1px solid #d5dce3;padding:7px 9px;text-align:right;vertical-align:top">{{line.qty}}</td><td style="border-bottom:1px solid #d5dce3;padding:7px 9px;text-align:right;vertical-align:top">{{line.rate}}</td><td style="border-bottom:1px solid #d5dce3;padding:7px 9px;text-align:right;vertical-align:top">{{line.amount}}</td></tr>{{/lines}}</tbody></table><div style="width:270px;margin-left:auto;margin-bottom:10px"><div style="display:flex;justify-content:space-between;padding:3px 0"><span>Subtotal</span><span>{{report.subtotal}}</span></div><div style="display:flex;justify-content:space-between;padding:3px 0"><span>Discount</span><span>{{report.discount}}</span></div><div style="display:flex;justify-content:space-between;padding:3px 0"><span>GST</span><span>{{report.gst}}</span></div><div style="display:flex;justify-content:space-between;border-top:2px solid #18222d;font-weight:700;font-size:14px;margin-top:4px;padding-top:6px"><span>Total</span><span>{{quotation.total}}</span></div></div><p style="margin:12px 0;color:#5d6b79">Valid until {{quotation.valid_until}}.</p><p>{{quotation.notes}}</p><p style="margin:8px 0;color:#5d6b79">Amount in words: <strong style="color:#18222d">{{report.amount_words}}</strong></p></div><div style="display:flex;justify-content:space-between;align-items:flex-end;margin-top:26px"><div>{{blocks.company_stamp}}</div><div style="text-align:center"><div style="min-height:44px;display:flex;align-items:flex-end;justify-content:center">{{blocks.authorized_signature}}</div><div style="border-top:1px solid #18222d;padding-top:4px;font-size:11px;width:180px">Authorised signatory<br>{{company.name}}</div></div></div><p style="border-top:1px solid #d5dce3;margin:14px 0 0;padding-top:8px;font-size:10.5px;color:#5d6b79">{{company.footer}}</p></div></main>
